def snap(t):
    lo, hi = 0, len(starts) - 1
    while lo < hi:
        m = (lo + hi) // 2
        if starts[m] < t:
            lo = m + 1
        else:
            hi = m
    a = starts[max(0, lo - 1)]
    b = starts[lo]
    return a if (t - a) <= (b - t) else b

